/// <summary>
/// init the form method
/// </summary>
public void init()
{
    date systemDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    super();
    ShipDateFilter.dateValue(systemDate);
    DaysForwardFilter.value(0);
    WaveOnlyFilter.checked(true);
}

/// <summary>
/// validate the form method
/// </summary>
/// <returns>return the boolean value</returns>
public boolean validate()
{
    #define.MinAllowedDaysBack(365)
    boolean ret = true;
    date today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    date minAllowedDate = today - #MinAllowedDaysBack;

    // Check if FromDateFilter is empty (mandatory check)
    if (!ShipDateFilter.dateValue())
    {
        checkFailed("@MET:ShipDateIsMandatory");
        ret = false;
    }
    // Check if From date is earlier than the minimum allowed date
    else if (ShipDateFilter.dateValue() < minAllowedDate)
    {
        checkFailed(strFmt("@MET:ShipDateCannotBeEarlier", minAllowedDate));
        ShipDateFilter.dateValue(minAllowedDate);
        ret = false;
    }

    // Check if Warehouse is empty (mandatory check)
    if (!InventlocationIdToFilter.valueStr() || !InventLocation::find(InventlocationIdToFilter.valueStr()))
    {
        checkFailed("@MET:WarehouseMandatory");
        ret = false;
    }

    return ret;
}

/// <summary>
/// Delete the current User Id Record
/// </summary>
public void DeleteRecord()
{
    ttsbegin;
    delete_from METCSDWaveTable ;
    ttscommit;
}

/// <summary>
/// InventTransferLine_DS run the execute query.
/// </summary>
public void executeQuery()
{
    super();
}

/// <summary>
/// execute the Query
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildRange         range2,range3;
    METCSDQtyDiff           CSDQtyDiff;
    NoYes                   showWaveOnly;

    CSDQtyDiff = str2Enum(CSDQtyDiff,QtyDiffFilter.valueStr());
    showWaveOnly = WaveOnlyFilter.checked();

    queryBuildDataSource = this.query().dataSourceTable(tablenum(METCSDWaveTable));
    queryBuildDataSource.clearRanges();

    if (CSDQtyDiff == METCSDQtyDiff::DiffernceOnly)
    {
        range2 = queryBuildDataSource.addRange(fieldnum(METCSDWaveTable, QtyDifference));
        range2.value(SysQuery::valueNot(0));
    }

    if (showWaveOnly == NoYes::Yes)
    {
        range3 = queryBuildDataSource.addRange(fieldnum(METCSDWaveTable, WaveId));
        range3.value(SysQuery::valueNot(''));
    }
    super();
}

/// <summary>
/// validate and apply filters
/// </summary>
public void clicked()
{
    InventLocation      inventLocation;
    InventLocationID    inventLocationId    = InventlocationIdToFilter.valueStr();
    int                 daysforward         = DaysForwardFilter.value();
    TransDate           fromDate            = ShipDateFilter.dateValue();
    NoYesId             waveOnly            = WaveOnlyFilter.checked();
    InventDim           inventDim;
    TransDate           toDate;

    if (daysforward > 0)
    {
        toDate = ShipDateFilter.dateValue() + daysforward;
    }
    inventLocation = InventLocation::find(inventLocationId);
    super();

    ttsbegin;
    element.DeleteRecord();
    ttscommit;

    if (element.validate())
    {
        if (daysforward > 0)
        {
            while select TransferId,ItemId,PdsCWQtyTransfer,QtyTransfer,QtyShipped,PdsCWQtyShipped,RecId,InventTransId from inventTransferLine
                join InventLocationIdTo,TransferId from inventTransferTable
                    where inventTransferTable.TransferId == inventTransferLine.TransferId
                        && inventTransferLine.ShipDate >= fromDate
                        && inventTransferLine.ShipDate <= toDate
                        && inventTransferTable.InventLocationIdTo == inventLocationId
            {
                METCSDWaveTable.ProductName = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber(inventTransferLine.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
                METCSDWaveTable.UnitId = InventTableModule::find(inventTransferLine.ItemId,ModuleInventPurchSales::Invent).UnitId;
                METCSDWaveTable.PdsCWUnitId = PdsCatchWeightItem::find(inventTransferLine.ItemId).PdsCWUnitId;
                METCSDWaveTable.CSDTOType = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId).CSDTOType;

                if (!inventTransferLine.PdsCWQtyTransfer)
                {
                    METCSDWaveTable.QtyDifference = inventTransferLine.QtyTransfer - inventTransferLine.QtyShipped;
                }
                else
                {
                    METCSDWaveTable.QtyDifference = inventTransferLine.PdsCWQtyTransfer - inventTransferLine.PdsCWQtyShipped;
                }

                if (waveOnly == NoYes::Yes && InventLocation::find(inventTransferTable.InventLocationIdTo).METWaveRequired)
                {
                    METCSDWaveTable.WaveId = METWaveLine::findByDocumentRefRecId(inventTransferLine.RecId).WaveId;
                    METCSDWaveTable.WaveNumber = METWaveTable::find(METWaveLine::findByDocumentRefRecId(inventTransferLine.RecId).WaveId).WaveNumber;

                }
                inventDim.clear();
                inventDim.InventLocationId = inventTransferTable.InventLocationIdTo;
                inventDim.InventSiteId = InventLocation::find(inventTransferTable.InventLocationIdTo).InventSiteId;
                inventDim = InventDim::findOrCreate(inventDim);

                METCSDWaveTable.SalesUnit = InventTable::find(inventTransferLine.ItemId).inventItemSalesSetup(inventDim.inventDimId).METSalesUnit;
                METCSDWaveTable.InventTransId = inventTransferLine.InventTransId;
                METCSDWaveTable.validateWrite();
                METCSDWaveTable.insert();
            }
        }
        else
        {
            while select TransferId,ItemId,PdsCWQtyTransfer,QtyTransfer,QtyShipped,PdsCWQtyShipped,RecId,InventTransId from inventTransferLine
                join InventLocationIdTo,TransferId from inventTransferTable
                    where inventTransferTable.TransferId == inventTransferLine.TransferId
                        && inventTransferLine.ShipDate == fromDate
                        && inventTransferTable.InventLocationIdTo == inventLocationId
            {
                METCSDWaveTable.ProductName = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber(inventTransferLine.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
                METCSDWaveTable.UnitId = InventTableModule::find(inventTransferLine.ItemId,ModuleInventPurchSales::Invent).UnitId;
                METCSDWaveTable.PdsCWUnitId = PdsCatchWeightItem::find(inventTransferLine.ItemId).PdsCWUnitId;
                METCSDWaveTable.CSDTOType = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId).CSDTOType;

                if (!inventTransferLine.PdsCWQtyTransfer)
                {
                    METCSDWaveTable.QtyDifference = inventTransferLine.QtyTransfer - inventTransferLine.QtyShipped;
                }
                else
                {
                    METCSDWaveTable.QtyDifference = inventTransferLine.PdsCWQtyTransfer - inventTransferLine.PdsCWQtyShipped;
                }

                if (waveOnly == NoYes::Yes && InventLocation::find(inventTransferTable.InventLocationIdTo).METWaveRequired)
                {
                    METCSDWaveTable.WaveId = METWaveLine::findByDocumentRefRecId(inventTransferLine.RecId).WaveId;
                    METCSDWaveTable.WaveNumber = METWaveTable::find(METWaveLine::findByDocumentRefRecId(inventTransferLine.RecId).WaveId).WaveNumber;

                }
                inventDim.clear();
                inventDim.InventLocationId = inventTransferTable.InventLocationIdTo;
                inventDim.InventSiteId = InventLocation::find(inventTransferTable.InventLocationIdTo).InventSiteId;
                inventDim = InventDim::findOrCreate(inventDim);

                METCSDWaveTable.SalesUnit = InventTable::find(inventTransferLine.ItemId).inventItemSalesSetup(inventDim.inventDimId).METSalesUnit;
                METCSDWaveTable.InventTransId = inventTransferLine.InventTransId;
                METCSDWaveTable.validateWrite();
                METCSDWaveTable.insert();
            }
        }
    }
    InventTransferLine_ds.research(true);
    InventTransferTable_ds.research(true);
    METCSDWaveTable_DS.research(true);
    METCSDWaveTable_DS.executeQuery();
    InventTransferLine_ds.executeQuery();
}

/// <summary>
/// modified the datasource of execute query
/// </summary>
/// <returns>return the boolean value.</returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    METCSDWaveTable_DS.executeQuery();
    InventTransferLine_ds.executeQuery();

    return ret;
}

